from databricks.sdk import WorkspaceClient

w = WorkspaceClient()
# COMMAND ----------

# Create scope: all-activity-types
try:
    w.secrets.create_scope(scope="all-activity-types")
    print("Created scope: all-activity-types")
except Exception as e:
    if "RESOURCE_ALREADY_EXISTS" in str(e):
        print("Scope already exists: all-activity-types")
    else:
        raise

# JDBC URL for AzureSqlSource lookup in activity 'lookup'
w.secrets.put_secret(scope="all-activity-types", key="jdbc-url", string_value="PLACEHOLDER")
print("Created secret: all-activity-types/jdbc-url")

# JDBC password for AzureSqlSource lookup in activity 'lookup'
w.secrets.put_secret(scope="all-activity-types", key="jdbc-password", string_value="PLACEHOLDER")
print("Created secret: all-activity-types/jdbc-password")

